function drawSpiral(i) {
	const len = 1;
	const nf = 35; // noise factor
	const nl = 10; // len of dev-vector
	let d = max(width, height) * 0.95;
	let a = -frameCount/60;
	beginShape();
	while(d > len) {
		const f = 1 - len/d; // 1..0
		let u = PI * d;
		const da = len/u * TAU;
		a += da;
		d -= da * len;
		const x = cos(a) * d * 0.5;
		const y = sin(a) * d * 0.5;
		const n = noise(x/300 + i, y/300 + i, frameCount/300) * TAU;
		const scl = len;
		const dx = scl * cos(n) * n;
		const dy = scl * sin(n) * (1-n);
		const dv = noise(x/nf, y/nf)
		vertex(x + dx, y + dy);
	}
	endShape();
}
